* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: #f5f7fa;
  color: #142033;
}

.nav-map {
  width: 100%;
  min-height: 100vh;
  padding: 14px;
  background: #f5f7fa;
}

.nav-header {
  height: 56px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.title {
  font-size: 18px;
  font-weight: 800;
}

.subtitle {
  margin-top: 3px;
  font-size: 12px;
  color: #667085;
}

.target-badge {
  padding: 8px 10px;
  border-radius: 6px;
  background: #eef4ff;
  color: #1849a9;
  font-size: 12px;
  font-weight: 800;
  border: 1px solid #b2ccff;
}

.nav-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 12px;
}

.floor-wrap {
  background: white;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 12px;
  min-height: 520px;
}

.floor {
  position: relative;
  height: 500px;
  border: 2px solid #243447;
  border-radius: 6px;
  overflow: hidden;
  background: linear-gradient(90deg, rgba(20, 32, 51, 0.05) 1px, transparent 1px), linear-gradient(rgba(20, 32, 51, 0.05) 1px, transparent 1px), #fff;
  background-size: 28px 28px;
}

.entry {
  position: absolute;
  left: 18px;
  top: 220px;
  width: 78px;
  height: 58px;
  background: #ecfdf3;
  border: 1px solid #12b76a;
  color: #067647;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  z-index: 4;
}

.route-line {
  position: absolute;
  height: 5px;
  background: repeating-linear-gradient(90deg, #f79009 0, #f79009 10px, transparent 10px, transparent 16px);
  transform-origin: left center;
  border-radius: 99px;
  z-index: 2;
  animation: moveRoute 1s linear infinite;
}

@keyframes moveRoute {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 32px 0;
  }
}
.bin {
  position: absolute;
  width: 60px;
  height: 44px;
  border-radius: 4px;
  border: 1px solid #b8c4d2;
  padding: 4px;
  cursor: pointer;
  background: #e7eef7;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
  z-index: 3;
}

.bin:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(20, 32, 51, 0.14);
}

.bin.assigned {
  background: #2f80ed;
  color: white;
  border-color: #1d5fbf;
}

.bin.full {
  background: #d92d20;
  color: white;
  border-color: #b42318;
}

.bin.target {
  background: #fdb022;
  color: #142033;
  border-color: #dc6803;
  box-shadow: 0 0 0 6px rgba(253, 176, 34, 0.25);
  animation: pulseTarget 1.2s ease-in-out infinite;
  z-index: 6;
}

@keyframes pulseTarget {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.08);
  }
}
.bin-code {
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bin-meta {
  font-size: 9px;
  text-align: right;
}

.side {
  background: white;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 12px;
  min-height: 520px;
}

.side-title {
  font-size: 11px;
  font-weight: 900;
  color: #667085;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.route-steps {
  display: grid;
  gap: 8px;
  margin-bottom: 18px;
}

.step {
  border: 1px solid #e4e7ec;
  border-radius: 6px;
  padding: 8px;
  font-size: 12px;
  background: #fbfcfe;
}

.step b {
  display: block;
  margin-bottom: 3px;
}

.product-info {
  font-size: 12px;
  line-height: 1.5;
  border: 1px solid #e4e7ec;
  border-radius: 6px;
  padding: 10px;
  background: #fbfcfe;
}

.empty-state {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #667085;
  font-weight: 700;
  font-size: 13px;
}

@media (max-width: 900px) {
  .nav-body {
    grid-template-columns: 1fr;
  }
  .side {
    min-height: auto;
  }
}

