let lastModel = {};
let lastLocations = [];
function safeText(value) {
  return String(value ?? "");
}
function byText(a, b) {
  return safeText(a).localeCompare(safeText(b), undefined, {
    numeric: true,
    sensitivity: "base"
  });
}
function normalizeLocations(rawLocations) {
  return rawLocations.map(loc => ({
    ...loc,
    locationId: loc.locationId || loc.id,
    locationCode: loc.locationCode || loc.code,
    locationName: loc.locationName || loc.name,
    zoneCode: loc.zoneCode || loc.zone_code,
    aisleCode: loc.aisleCode || loc.aisle_code,
    rackCode: loc.rackCode || loc.rack_code,
    shelfCode: loc.shelfCode || loc.shelf_code,
    binCode: loc.binCode || loc.bin_code,
    productCount: loc.productCount || loc.product_count || 0,
    capacityPercent: loc.capacityPercent || loc.capacity_percent || 0
  }));
}
function statusClass(loc) {
  if (Number(loc.capacityPercent || 0) >= 100) return "full";
  if (Number(loc.productCount || 0) > 0) return "assigned";
  return "";
}
function getPosition(loc, index) {
  const aisleNumber = Number(String(loc.aisleCode || "").replace(/\D/g, "")) || 1;
  const rackNumber = Number(String(loc.rackCode || "").replace(/\D/g, "")) || 1;
  const shelfNumber = Number(String(loc.shelfCode || "").replace(/\D/g, "")) || 1;
  const binNumber = Number(String(loc.binCode || "").replace(/\D/g, "")) || 1;
  const x = 130 + (rackNumber - 1) * 190 + (binNumber - 1) * 66;
  const y = 50 + (aisleNumber - 1) * 100 + (shelfNumber - 1) * 48;
  return {
    x: Math.min(x, 760),
    y: Math.min(y, 430)
  };
}
function drawRoute(floor, from, to) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.sqrt(dx * dx + dy * dy);
  const angle = Math.atan2(dy, dx) * 180 / Math.PI;
  const line = document.createElement("div");
  line.className = "route-line";
  line.style.left = `${from.x}px`;
  line.style.top = `${from.y}px`;
  line.style.width = `${length}px`;
  line.style.transform = `rotate(${angle}deg)`;
  floor.appendChild(line);
}
function renderProduct(product, targetLocation) {
  const productInfo = document.getElementById("productInfo");
  if (!product || !product.productId) {
    productInfo.innerHTML = "No product selected.";
    return;
  }
  productInfo.innerHTML = `
    <b>${safeText(product.productCode)}</b><br>
    ${safeText(product.productName)}<br>
    Barcode: ${safeText(product.barcode)}<br>
    Stock: ${safeText(product.warehouseStock || 0)}<br>
    Location: ${safeText(targetLocation?.locationCode || product.locationCode || "")}
  `;
}
function renderSteps(targetLocation) {
  const routeSteps = document.getElementById("routeSteps");
  if (!targetLocation) {
    routeSteps.innerHTML = `
      <div class="step">
        <b>No route</b>
        Search product to start navigation.
      </div>
    `;
    return;
  }
  routeSteps.innerHTML = `
    <div class="step">
      <b>1. Start</b>
      Enter warehouse from receiving / main entrance.
    </div>
    <div class="step">
      <b>2. Go to aisle</b>
      Aisle ${safeText(targetLocation.aisleCode || "-")}
    </div>
    <div class="step">
      <b>3. Find rack</b>
      Rack ${safeText(targetLocation.rackCode || "-")}
    </div>
    <div class="step">
      <b>4. Pick position</b>
      Shelf ${safeText(targetLocation.shelfCode || "-")}, Bin ${safeText(targetLocation.binCode || "-")}
    </div>
  `;
}
function render(model) {
  lastModel = model || {};
  lastLocations = normalizeLocations(Array.isArray(lastModel.locations) ? lastModel.locations : []);
  const targetId = Number(lastModel.targetLocationId || 0);
  const product = lastModel.product || {};
  const floor = document.getElementById("floor");
  const subtitle = document.getElementById("subtitle");
  const targetBadge = document.getElementById("targetBadge");
  if (!lastLocations.length) {
    floor.innerHTML = `<div class="empty-state">No warehouse locations loaded.</div>`;
    renderSteps(null);
    renderProduct(product, null);
    return;
  }
  const targetLocation = lastLocations.find(x => Number(x.locationId) === targetId);
  subtitle.innerText = targetLocation ? `Route calculated to ${targetLocation.locationCode}` : `${lastLocations.length} locations loaded`;
  targetBadge.innerText = targetLocation ? `Target: ${targetLocation.locationCode}` : "No target";
  floor.innerHTML = `<div class="entry">Entry / Receiving</div>`;
  const entryPoint = {
    x: 96,
    y: 249
  };
  let targetPoint = null;
  lastLocations.forEach((loc, index) => {
    const id = Number(loc.locationId || 0);
    const pos = getPosition(loc, index);
    const isTarget = id === targetId;
    if (isTarget) {
      targetPoint = {
        x: pos.x + 30,
        y: pos.y + 22
      };
    }
    const el = document.createElement("div");
    el.className = `bin ${statusClass(loc)} ${isTarget ? "target" : ""}`;
    el.style.left = `${pos.x}px`;
    el.style.top = `${pos.y}px`;
    el.title = safeText(loc.locationName);
    el.innerHTML = `
      <div class="bin-code">${safeText(loc.locationCode)}</div>
      <div class="bin-meta">${safeText(loc.capacityPercent || 0)}%</div>
    `;
    floor.appendChild(el);
  });
  if (targetPoint) {
    drawRoute(floor, entryPoint, targetPoint);
  }
  renderSteps(targetLocation);
  renderProduct(product, targetLocation);
}
if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(() => {
    render(appsmith.model || {});
  });
}
if (window.appsmith && appsmith.onModelChange) {
  appsmith.onModelChange(model => {
    render(model || {});
  });
}
setTimeout(() => {
  render(window.appsmith?.model || {});
}, 400);

